// Generated by Selenium IDE
const { Builder, By, Key, until } = require('selenium-webdriver')
const assert = require('assert')
describe('Missing Tooth', function() {
  this.timeout(60000)
  let driver
  let vars
  beforeEach(async function() {
    driver = await new Builder().forBrowser('firefox').build()
    vars = {}
  })
  afterEach(async function() {
    await driver.quit()
  })
  async function handleAlert(driver) {
    try {await driver.wait(until.alertIsPresent(),1000);const alert=await driver.switchTo().alert();await alert.accept()}catch(e){}
  }
  it('Missing Tooth', async function() {
    await driver.get("http://localhost:3000/login")
    await driver.manage().window().setRect({ width: 1064, height: 784 })
    const passInput = await driver.wait(until.elementLocated(By.id("password")),8000)
    await passInput.sendKeys("dentabase")
    const loginBtn = await driver.wait(until.elementLocated(By.id("login-button")),8000)
    await loginBtn.click()
    await driver.wait(until.urlContains("/to-do"),8000)
    await handleAlert(driver)
    const patientMenu = await driver.wait(until.elementLocated(By.css('a[href="/patient_list"] span.sidebar-text')),8000)
    await patientMenu.click()
    await handleAlert(driver)
    const johnDoe = await driver.wait(until.elementLocated(By.css('a.name')),8000)
    await johnDoe.click()
    await handleAlert(driver)
    const dentalChart = await driver.wait(until.elementLocated(By.css('a.nav-item[href="#dental-record-chart"]')),8000)
    await dentalChart.click()
    await handleAlert(driver)
    const missingBtn = await driver.wait(until.elementLocated(By.css(".dc-code-grid:nth-child(3) > .dc-code-btn:nth-child(3)")),8000)
    await driver.executeScript("arguments[0].scrollIntoView({block:'center'});",missingBtn)
    await driver.executeScript("arguments[0].click();",missingBtn)
    await handleAlert(driver)
    const tooth = await driver.wait(until.elementLocated(By.css("#q1 > .tooth-container:nth-child(7) .s-center")),8000)
    await driver.executeScript("arguments[0].scrollIntoView({block:'center'});",tooth)
    await driver.executeScript("arguments[0].click();",tooth)
    await handleAlert(driver)
    const tool = await driver.wait(until.elementLocated(By.css(".dc-tool-btn:nth-child(7)")),8000)
    await driver.executeScript("arguments[0].click();",tool)
    await handleAlert(driver)
    const selectedSpot = await driver.wait(until.elementLocated(By.css(".selected .s-left")),8000)
    await driver.executeScript("arguments[0].scrollIntoView({block:'center'});",selectedSpot)
    await driver.executeScript("arguments[0].click();",selectedSpot)
    await handleAlert(driver)
    const saveBtn = await driver.wait(until.elementLocated(By.css(".dc-save-btn")),8000)
    await driver.executeScript("arguments[0].scrollIntoView({block:'center'});",saveBtn)
    await driver.executeScript("arguments[0].click();",saveBtn)
    await driver.wait(until.alertIsPresent(),5000)
    const alert = await driver.switchTo().alert()
    const text = await alert.getText()
    assert.strictEqual(text,"Dental Chart Saved Successfully!")
    await alert.accept()
  })
})